// schemaProfileBody is the zatiti.serenity/v2 profile document schema
// (SerenityProfile), transcribed from the frozen catalog.
const schemaProfileBody = `{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"backup_revision_protocol":{"$ref":"#/$defs/SerenityBackupProtocol"},"brain_mappings":{"items":{"oneOf":[{"$ref":"#/$defs/SerenityBrainMapping"},{"$ref":"#/$defs/SerenityHostedBrainMapping"}]},"maxItems":4096,"minItems":0,"type":"array"},"capability_evidence":{"$ref":"#/$defs/CapabilityEvidence"},"command_status_lookup":{"$ref":"#/$defs/SerenityLookupSemantics"},"commit":{"maxLength":128,"minLength":1,"type":"string"},"enforcement":{"$ref":"#/$defs/BoundEnforcement"},"freshness":{"$ref":"#/$defs/SerenityFreshnessCapability"},"max_bytes":{"maximum":268435456,"minimum":1,"type":"integer"},"schema":{"const":"zatiti.serenity/v2","type":"string"},"supported_operations":{"items":{"enum":["recall","remember","inspect","promote","retract","export_revision"],"type":"string"},"maxItems":6,"minItems":0,"type":"array"},"timeout_seconds":{"maximum":1800,"minimum":1,"type":"integer"},"version":{"maxLength":128,"minLength":1,"type":"string"}},"required":["schema","version","commit","brain_mappings","supported_operations","enforcement","command_status_lookup","freshness","timeout_seconds","max_bytes","backup_revision_protocol","capability_evidence"],"type":"object"}`

// schemaParametersBody is the zatiti.serenity.action/v1 discriminated union
// (SerenityParameters): exactly one of the six action kinds.
const schemaParametersBody = `{"$schema":"https://json-schema.org/draft/2020-12/schema","oneOf":[{"$ref":"#/$defs/SerenityRecall"},{"$ref":"#/$defs/SerenityRemember"},{"$ref":"#/$defs/SerenityInspect"},{"$ref":"#/$defs/SerenityPromote"},{"$ref":"#/$defs/SerenityRetract"},{"$ref":"#/$defs/SerenityExportRevision"}]}`

// schemaEvidenceBody is the zatiti.serenity.evidence/v1 document schema
// (SerenityEvidence).
const schemaEvidenceBody = `{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"active_recall_removed":{"type":"boolean"},"adapter_command_id":{"$ref":"#/$defs/ID"},"brain_id":{"$ref":"#/$defs/ID"},"brain_revisions":{"items":{"$ref":"#/$defs/BrainRevision"},"maxItems":64,"minItems":0,"type":"array"},"claims":{"items":{"$ref":"#/$defs/MemoryClaim"},"maxItems":200,"minItems":0,"type":"array"},"command_status":{"enum":["not_admitted","accepted","completed","failed","unknown"],"type":"string"},"historical_erasure":{"const":false,"type":"boolean"},"kind":{"enum":["recall","remember","inspect","promote","retract","export_revision"],"type":"string"},"lookup_authoritative":{"type":"boolean"},"output_artifacts":{"items":{"$ref":"#/$defs/ArtifactRef"},"maxItems":256,"minItems":0,"type":"array"},"physical_call":{"$ref":"#/$defs/PhysicalCallEvidence"},"schema":{"const":"zatiti.serenity.evidence/v1","type":"string"},"selected_context":{"$ref":"#/$defs/ArtifactLocator"},"staged_outputs":{"items":{"$ref":"#/$defs/StagedOutput"},"maxItems":256,"minItems":0,"type":"array"},"usage":{"$ref":"#/$defs/ProviderUsage"},"writer_owner":{"maxLength":512,"minLength":1,"type":"string"}},"required":["schema","physical_call","kind","brain_id","adapter_command_id","command_status","claims","brain_revisions","usage","staged_outputs","output_artifacts"],"type":"object"}`

// composeOnce lazily composes the three operation-shaped documents with the
// shared $defs catalog. Composition happens once; documents are immutable.
var (
	composeOnce         sync.Once
	composedProfile     json.RawMessage
	composedParameters  json.RawMessage
	composedEvidence    json.RawMessage
	composeSchemaErrVal error
)

func composeSchemas() error {
	composeOnce.Do(func() {
		// The catalog is spliced verbatim: decoding it into json.RawMessage
		// values round-trips no number through float64, so frozen integer
		// bounds like the int64 maximum survive composition exactly.
		var doc map[string]json.RawMessage
		if err := contract.DecodeStrict([]byte(schemaDefs), &doc); err != nil {
			composeSchemaErrVal = fmt.Errorf("serenity: embedded $defs catalog is not valid JSON: %w", err)
			return
		}
		defs, ok := doc["$defs"]
		if !ok {
			composeSchemaErrVal = fmt.Errorf("serenity: embedded $defs catalog has no $defs object")
			return
		}
		var err error
		if composedProfile, err = withDefs(schemaProfileBody, defs); err != nil {
			composeSchemaErrVal = err
			return
		}
		if composedParameters, err = withDefs(schemaParametersBody, defs); err != nil {
			composeSchemaErrVal = err
			return
		}
		if composedEvidence, err = withDefs(schemaEvidenceBody, defs); err != nil {
			composeSchemaErrVal = err
			return
		}
	})
	return composeSchemaErrVal
}

// withDefs returns body with the $defs catalog injected at the document
// root, so every #/$defs/... reference resolves document-locally.
func withDefs(body string, defs json.RawMessage) (json.RawMessage, error) {
	var doc map[string]json.RawMessage
	if err := json.Unmarshal([]byte(body), &doc); err != nil {
		return nil, fmt.Errorf("serenity: operation schema is not valid JSON: %w", err)
	}
	if _, ok := doc["$defs"]; ok {
		return nil, fmt.Errorf("serenity: operation schema already declares $defs: %s", body)
	}
	doc["$defs"] = defs
	out, err := json.Marshal(doc)
	if err != nil {
		return nil, fmt.Errorf("serenity: schema composition failed: %w", err)
	}
	return json.RawMessage(out), nil
}

// profileSchema returns the composed zatiti.serenity/v2 profile schema.
func profileSchema() (json.RawMessage, error) {
	if err := composeSchemas(); err != nil {
		return nil, err
	}
	return composedProfile, nil
}

// parametersSchema returns the composed zatiti.serenity.action/v1 schema.
func parametersSchema() (json.RawMessage, error) {
	if err := composeSchemas(); err != nil {
		return nil, err
	}
	return composedParameters, nil
}

// evidenceSchema returns the composed zatiti.serenity.evidence/v1 schema.
func evidenceSchema() (json.RawMessage, error) {
	if err := composeSchemas(); err != nil {
		return nil, err
	}
	return composedEvidence, nil
}
